-- Size guides (Phase 29): a chart per product, or a category default
CREATE TABLE "SizeChart" (
  "id" UUID NOT NULL,
  "storeId" UUID,
  "name" TEXT NOT NULL,
  "nameAr" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'CLOTHING',
  "columns" JSONB NOT NULL,
  "rows" JSONB NOT NULL,
  "note" TEXT,
  "noteAr" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "SizeChart_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "SizeChart_storeId_idx" ON "SizeChart"("storeId");
ALTER TABLE "SizeChart" ADD CONSTRAINT "SizeChart_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Category" ADD COLUMN "sizeChartId" UUID;
ALTER TABLE "Category" ADD CONSTRAINT "Category_sizeChartId_fkey" FOREIGN KEY ("sizeChartId") REFERENCES "SizeChart"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Product" ADD COLUMN "sizeChartId" UUID;
ALTER TABLE "Product" ADD CONSTRAINT "Product_sizeChartId_fkey" FOREIGN KEY ("sizeChartId") REFERENCES "SizeChart"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Ready-made FastMoveX charts (staff can edit or add more in the admin panel)
INSERT INTO "SizeChart" ("id","storeId","name","nameAr","kind","columns","rows","note","noteAr","updatedAt") VALUES ('5a1e0001-0000-4000-8000-000000000001',NULL,'Men''s clothing (shirts & T-shirts)','ملابس رجالية (القمصان والتيشيرتات)','CLOTHING','[{"label": "Size", "labelAr": "المقاس", "unit": null}, {"label": "Chest", "labelAr": "الصدر", "unit": "cm"}, {"label": "Waist", "labelAr": "الخصر", "unit": "cm"}, {"label": "Sleeve", "labelAr": "الكم", "unit": "cm"}]'::jsonb,'[["XS", "84–89", "71–76", "79"], ["S", "89–94", "76–81", "81"], ["M", "97–102", "84–89", "83"], ["L", "107–112", "94–99", "85"], ["XL", "117–122", "104–109", "87"], ["XXL", "127–132", "114–119", "89"], ["3XL", "137–142", "124–129", "91"]]'::jsonb,'Measure over a thin T-shirt. If you are between two sizes, choose the larger one.','قِس فوق قميص خفيف. إذا كنت بين مقاسين فاختر الأكبر.',CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "SizeChart" ("id","storeId","name","nameAr","kind","columns","rows","note","noteAr","updatedAt") VALUES ('5a1e0001-0000-4000-8000-000000000002',NULL,'Women''s clothing','ملابس نسائية','CLOTHING','[{"label": "Size", "labelAr": "المقاس", "unit": null}, {"label": "UK", "labelAr": "بريطاني", "unit": null}, {"label": "EU", "labelAr": "أوروبي", "unit": null}, {"label": "Bust", "labelAr": "الصدر", "unit": "cm"}, {"label": "Waist", "labelAr": "الخصر", "unit": "cm"}, {"label": "Hips", "labelAr": "الأرداف", "unit": "cm"}]'::jsonb,'[["XS", "6", "34", "80–83", "62–65", "87–90"], ["S", "8", "36", "84–87", "66–69", "91–94"], ["M", "10–12", "38–40", "88–95", "70–77", "95–102"], ["L", "14", "42", "96–100", "78–82", "103–107"], ["XL", "16", "44", "101–105", "83–87", "108–112"], ["XXL", "18", "46", "106–111", "88–93", "113–118"]]'::jsonb,'Sizes can differ a little between brands. If you are between two sizes, choose the larger one.','قد تختلف المقاسات قليلاً بين الماركات. إذا كنتِ بين مقاسين فاختاري الأكبر.',CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "SizeChart" ("id","storeId","name","nameAr","kind","columns","rows","note","noteAr","updatedAt") VALUES ('5a1e0001-0000-4000-8000-000000000003',NULL,'Thobe / kandura','ثوب / كندورة','LENGTH','[{"label": "Size", "labelAr": "المقاس", "unit": null}, {"label": "Length", "labelAr": "الطول", "unit": "in"}, {"label": "Your height", "labelAr": "طولك", "unit": "cm"}]'::jsonb,'[["50", "50", "150–155"], ["52", "52", "155–160"], ["54", "54", "160–165"], ["56", "56", "165–170"], ["58", "58", "170–175"], ["60", "60", "175–180"], ["62", "62", "180–185"], ["64", "64", "185–190"]]'::jsonb,'A thobe''s size is its length in inches, from the shoulder to the hem.','مقاس الثوب هو طوله بالإنش، من الكتف إلى الأسفل.',CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "SizeChart" ("id","storeId","name","nameAr","kind","columns","rows","note","noteAr","updatedAt") VALUES ('5a1e0001-0000-4000-8000-000000000004',NULL,'Abaya','عباية','LENGTH','[{"label": "Size", "labelAr": "المقاس", "unit": null}, {"label": "Length", "labelAr": "الطول", "unit": "in"}, {"label": "Your height", "labelAr": "طولك", "unit": "cm"}]'::jsonb,'[["50", "50", "150–155"], ["52", "52", "155–160"], ["54", "54", "160–165"], ["56", "56", "165–170"], ["58", "58", "170–175"], ["60", "60", "175–180"], ["62", "62", "180–185"]]'::jsonb,'An abaya''s size is its length in inches, from the shoulder to the hem. Choose the one that reaches your ankle.','مقاس العباية هو طولها بالإنش، من الكتف إلى الأسفل. اختاري المقاس الذي يصل إلى الكاحل.',CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "SizeChart" ("id","storeId","name","nameAr","kind","columns","rows","note","noteAr","updatedAt") VALUES ('5a1e0001-0000-4000-8000-000000000005',NULL,'Shoes','الأحذية','SHOES','[{"label": "EU", "labelAr": "أوروبي", "unit": null}, {"label": "UK", "labelAr": "بريطاني", "unit": null}, {"label": "US men", "labelAr": "أمريكي رجالي", "unit": null}, {"label": "US women", "labelAr": "أمريكي نسائي", "unit": null}, {"label": "Foot length", "labelAr": "طول القدم", "unit": "cm"}]'::jsonb,'[["36", "3.5", "4.5", "6", "22.5"], ["37", "4", "5", "6.5", "23"], ["38", "5", "6", "7.5", "24"], ["39", "6", "7", "8.5", "24.5"], ["40", "6.5", "7.5", "9", "25"], ["41", "7.5", "8.5", "10", "26"], ["42", "8", "9", "10.5", "26.5"], ["43", "9", "10", "11.5", "27.5"], ["44", "9.5", "10.5", "12", "28"], ["45", "10.5", "11.5", "13", "29"], ["46", "11", "12", "—", "29.5"]]'::jsonb,'Measure your foot in the evening, standing, from the heel to the longest toe. Between two sizes? Take the larger one.','قِس قدمك مساءً وأنت واقف، من الكعب إلى أطول إصبع. بين مقاسين؟ اختر الأكبر.',CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "SizeChart" ("id","storeId","name","nameAr","kind","columns","rows","note","noteAr","updatedAt") VALUES ('5a1e0001-0000-4000-8000-000000000006',NULL,'Kids'' clothing','ملابس الأطفال','KIDS','[{"label": "Age", "labelAr": "العمر", "unit": null}, {"label": "Height", "labelAr": "الطول", "unit": "cm"}, {"label": "Chest", "labelAr": "الصدر", "unit": "cm"}]'::jsonb,'[["2–3 y", "92–98", "52–54"], ["3–4 y", "98–104", "54–56"], ["4–5 y", "104–110", "56–58"], ["5–6 y", "110–116", "58–60"], ["6–7 y", "116–122", "60–62"], ["7–8 y", "122–128", "62–64"], ["9–10 y", "134–140", "66–70"], ["11–12 y", "146–152", "72–76"], ["13–14 y", "158–164", "78–82"]]'::jsonb,'Go by height rather than age. Growing fast? Choose the next size up.','اعتمد على الطول وليس العمر. إذا كان الطفل يكبر بسرعة فاختر المقاس الأكبر.',CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;

-- Defaults: shoes and children's categories (and their subcategories) get the matching guide
UPDATE "Category" SET "sizeChartId" = '5a1e0001-0000-4000-8000-000000000005' WHERE "slug" = 'shoes' AND "sizeChartId" IS NULL;
UPDATE "Category" SET "sizeChartId" = '5a1e0001-0000-4000-8000-000000000006' WHERE "slug" = 'baby-kids' AND "sizeChartId" IS NULL;
